export type ParsedOpenPositionInstruction<
  TProgram extends string = typeof LEVERMEME_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    protocol: TAccountMetas[1];
    listing: TAccountMetas[2];
    market: TAccountMetas[3];
    margin: TAccountMetas[4];
    position: TAccountMetas[5];
    quoteMint: TAccountMetas[6];
    userVault: TAccountMetas[7];
    marketVault: TAccountMetas[8];
    quoteProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: OpenPositionInstructionData;
};

export function parseOpenPositionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenPositionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      protocol: getNextAccount(),
      listing: getNextAccount(),
      market: getNextAccount(),
      margin: getNextAccount(),
      position: getNextAccount(),
      quoteMint: getNextAccount(),
      userVault: getNextAccount(),
      marketVault: getNextAccount(),
      quoteProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getOpenPositionInstructionDataDecoder().decode(instruction.data),
  };
}
